/**
 * sfx-shelf/sets/mouth — mouth foley: swishes, swooshes and swings made the way a vocal sound-effect performer makes
 * them, then traced into recipes. The local voice worker (Kokoro) says a sound word that already sounds like the thing
 * (Japanese manga words: シュッ shu', ザシュッ zashu', ヒュン hyun, ブン bun, スパッ supa' …), a chain cuts the vowel out
 * and sweeps, pans and layers the breath, and the result is traced (trace.js) into a `trace` gesture the kernel
 * synthesizes back. No sample is stored: the traces are numbers (sets/mouth-traces.js, generated by
 * `scripts/mouth-foley/bake.mjs`), and only a re-bake needs the worker. Pure data.
 *
 * A trace with `with` is laid under a family's own cue, its loudest moment on the cue's (the katana's swing with the
 * voice 6 dB under it): the synth keeps its attack, the mouth fills the band between.
 */
import { familyCue } from '../families.js';
import { freeze } from '../layers.js';
import { MOUTH_TRACES } from './mouth-traces.js';

export const MOUTH = freeze({
  label: 'Mouth foley',
  cues: Object.fromEntries(Object.entries(MOUTH_TRACES).map(([id, e]) => [id, e.with ? [...familyCue(e.with.family, e.with.dials), e.trace] : [e.trace]])),
});
